"""A failed PR search keeps the last good results instead of wiping them."""

from pathlib import Path
from unittest.mock import patch

from personal_assistant_dashboard.prs_tab import EMPTY_CONFIRM_REFRESHES, PrsTab

MOD = "personal_assistant_dashboard.prs_tab"
OLD_REVIEW = [{"html_url": "old-r", "title": "old review"}]
OLD_MY = [{"html_url": "old-m", "title": "old mine"}]
NEW_REVIEW = [{"html_url": "new-r", "title": "new review"}]
NEW_MY = [{"html_url": "new-m", "title": "new mine"}]


def _tab(tmp_path: Path) -> PrsTab:
    tab = PrsTab.__new__(PrsTab)
    tab._state_path = tmp_path
    tab._review_prs = OLD_REVIEW
    tab._my_prs = OLD_MY
    tab._requested_urls = {"old-r"}
    tab._direct_urls = {"old-r"}
    tab._empty_streak = {}
    tab._scheduled = []

    def _capture(fn, *args):
        tab._scheduled.append((fn, args))

    tab._schedule = _capture
    return tab


def _refresh(tab: PrsTab, failing: str, empty: str = "no-such-query") -> tuple:
    """Run _do_refresh with every search whose query contains `failing`
    failing, and every one containing `empty` succeeding with no items."""

    def _fake_fetch(query, tally):
        if failing in query:
            tally.record(query, 1, "rate limited")
            return None
        tally.record(query, 0, "")
        if empty in query:
            return []
        if "author:@me" in query and "-author" not in query:
            return list(NEW_MY)
        if "reviewed-by" in query:
            return []
        return list(NEW_REVIEW)

    with (
        patch(f"{MOD}._fetch_prs", side_effect=_fake_fetch),
        patch(f"{MOD}._fetch_review_meta", return_value={}),
        patch(f"{MOD}._fetch_incoming_change_requests", return_value={}),
        patch(f"{MOD}._fetch_pr_details", return_value=(set(), {}, {})),
    ):
        tab._do_refresh()
    loaded = [args for fn, args in tab._scheduled if fn == tab._on_data_loaded]
    assert len(loaded) == 1
    tab._last_tally = [a[0] for fn, a in tab._scheduled if fn == tab._apply_health][0]
    tab._scheduled.clear()
    return loaded[0]


def test_failed_review_search_keeps_previous_review_side(tmp_path: Path):
    tab = _tab(tmp_path)
    review, my, _, _, _, requested, direct, _, _ = _refresh(
        tab, "user-review-requested"
    )
    assert review == OLD_REVIEW
    assert requested == {"old-r"}
    assert direct == {"old-r"}
    assert my == NEW_MY
    # Unchanged direct set means no spurious new-review-request alert.
    assert direct - tab._direct_urls == set()


def test_failed_my_search_keeps_previous_my_prs(tmp_path: Path):
    tab = _tab(tmp_path)
    review, my, _, _, _, requested, direct, _, _ = _refresh(tab, "+author:@me")
    assert my == OLD_MY
    assert review == NEW_REVIEW
    assert requested == direct == {"new-r"}


def test_all_searches_ok_replaces_everything(tmp_path: Path):
    tab = _tab(tmp_path)
    review, my, *_ = _refresh(tab, "no-such-query")
    assert review == NEW_REVIEW
    assert my == NEW_MY


def test_sudden_empty_search_keeps_previous_and_warns(tmp_path: Path):
    tab = _tab(tmp_path)
    review, my, *_ = _refresh(tab, "no-such-query", empty="+review-requested")
    assert review == OLD_REVIEW
    assert my == NEW_MY
    assert tab._last_tally.status == "warning"


def test_empty_search_accepted_after_repeats(tmp_path: Path):
    tab = _tab(tmp_path)
    for _ in range(EMPTY_CONFIRM_REFRESHES - 1):
        review, *_ = _refresh(tab, "no-such-query", empty="+author:@me")
        assert review == NEW_REVIEW
    _, my, *_ = _refresh(tab, "no-such-query", empty="+author:@me")
    assert my == []
    assert tab._last_tally.status == "ok"


def test_empty_search_accepted_when_previously_empty(tmp_path: Path):
    tab = _tab(tmp_path)
    tab._my_prs = []
    _, my, *_ = _refresh(tab, "no-such-query", empty="+author:@me")
    assert my == []
    assert tab._last_tally.status == "ok"
